{
  "implementation": "def solve(case):
    nodes = case["nodes"]
    required_symbols = set(case["required_symbols"])
    node_map = {}
    children = {}
    for n in nodes:
        nid = n["id"]
        node_map[nid] = n
        parent = n.get("parent")
        if parent is not None:
            children.setdefault(parent, []).append(nid)
    retained = set(node_map.keys())
    removed_order = []
    symbol_counts = {}
    for n in nodes:
        sym = n["symbol"]
        symbol_counts[sym] = symbol_counts.get(sym, 0) + 1
    sorted_nodes = sorted(nodes, key=lambda x: (-x["depth"], x["id"]))
    for n in sorted_nodes:
        nid = n["id"]
        if not n["removable"]:
            continue
        child_ids = children.get(nid, [])
        has_retained_child = any(cid in retained for cid in child_ids)
        if has_retained_child:
            continue
        sym = n["symbol"]
        if sym in required_symbols and symbol_counts[sym] <= 1:
            continue
        retained.remove(nid)
        removed_order.append(nid)
        symbol_counts[sym] -= 1
    retained_sorted = sorted(retained)
    return {
        "removed_node_ids": removed_order,
        "retained_node_ids": retained_sorted
    }"
}
